// icon returns inline SVG for a ligature name. If unknown, returns a generic dot SVG to avoid raw text.
func icon(name string) template.HTML {
	if svg, ok := iconSVGMap[name]; ok {
		return template.HTML(svg)
	}
	// fallback: generic placeholder (prevents "play_arrow" text flash)
	return template.HTML(`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-4 h-4 shrink-0"><circle cx="12" cy="12" r="3"/></svg>`)
}

// iconWithClass returns inline SVG with custom wrapper classes (size override)
// e.g. {{iconWithClass .Icon "w-6 h-6"}} or {{iconWithClass .Icon "!text-3xl"}}
func iconWithClass(name, classes string) template.HTML {
	base, ok := iconSVGMap[name]
	if !ok {
		base = `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-4 h-4 shrink-0"><circle cx="12" cy="12" r="3"/></svg>`
	}
	if classes == "" {
		return template.HTML(base)
	}
	return template.HTML(mergeSVGClass(base, classes))
}

// helper to merge classes – replaces size classes if extra provides w-/h-
func mergeSVGClass(svg, extra string) string {
	const needle = `class="`
	idx := indexOf(svg, needle)
	if idx < 0 {
		return svg
	}
	start := idx + len(needle)
	end := indexOfFrom(svg, `"`, start)
	if end < 0 {
		return svg
	}
	orig := svg[start:end]
	// if extra provides explicit w-*/h-* sizing, drop original w-*/h-* to avoid conflict
	hasW := containsToken(extra, "w-")
	hasH := containsToken(extra, "h-")
	var filtered string
	if hasW || hasH {
		// filter orig tokens
		toks := splitFields(orig)
		var keep []string
		for _, t := range toks {
			if hasW && len(t) > 2 && t[0] == 'w' && t[1] == '-' {
				continue
			}
			if hasH && len(t) > 2 && t[0] == 'h' && t[1] == '-' {
				continue
			}
			keep = append(keep, t)
		}
		filtered = joinFields(keep)
	} else {
		filtered = orig
	}
	merged := filtered + " " + extra
	return svg[:start] + merged + svg[end:]
}

func containsToken(s, prefix string) bool {
	for _, f := range splitFields(s) {
		if len(f) >= len(prefix) && f[:len(prefix)] == prefix {
			return true
		}
	}
	return false
}
func splitFields(s string) []string {
	var out []string
	cur := ""
	for i := 0; i < len(s); i++ {
		if s[i] == ' ' || s[i] == '\t' || s[i] == '\n' {
			if cur != "" {
				out = append(out, cur)
				cur = ""
			}
		} else {
			cur += string(s[i])
		}
	}
	if cur != "" {
		out = append(out, cur)
	}
	return out
}
func joinFields(a []string) string {
	res := ""
	for i, v := range a {
		if i > 0 {
			res += " "
		}
		res += v
	}
	return res
}

func indexOf(s, substr string) int {
	for i := 0; i < len(s)-len(substr)+1; i++ {
		if s[i:i+len(substr)] == substr {
			return i
		}
	}
	return -1
}
func indexOfFrom(s, substr string, from int) int {
	for i := from; i < len(s)-len(substr)+1; i++ {
		if s[i:i+len(substr)] == substr {
			return i
		}
	}
	return -1
}
